/**
 * bug6047 真实数据浏览器联调验证（只读）
 *
 * 目标：价格备案-价格备案申请 → 项目名称选择弹窗 → 「项目所在地」列有值。
 * 只做打开弹窗 + 读取表格文本 + 截图，不做任何保存/提交。
 *
 * 运行： node e2e/scripts/verify-bug6047-real.mjs
 * 依赖： E2E_BASE_URL 指向 nginx 部署站点（默认 http://127.0.0.1:8098）
 */
import fs from 'fs'
import path from 'path'
import { chromium } from '@playwright/test'
import { loadE2eEnv, getLoginUsername, getLoginPassword, getLoginType } from '../fixtures/env-loader.js'
import { loginWithRealAccount } from '../fixtures/auth-helpers.js'

loadE2eEnv()

const BASE_URL = process.env.E2E_BASE_URL || 'http://127.0.0.1:8098'
const OUT_DIR = path.resolve('e2e/output/bug6047')
fs.mkdirSync(OUT_DIR, { recursive: true })

/** 价格备案申请列表路由（与 PRICE_FILING_MENUS 一致） */
const LIST_PATH = '/#/commercialHousingSales/priceFiling/recordPriceMngSuzhou/index?menuId=6378'

function log(...a) {
  console.log('[bug6047]', ...a)
}

async function main() {
  const browser = await chromium.launch({ headless: process.env.HEADED === '1' ? false : true })
  const context = await browser.newContext({ viewport: { width: 1920, height: 911 } })
  const page = await context.newPage()

  const apiErrors = []
  page.on('response', (r) => {
    const u = r.url()
    if (u.includes('/api/v3.0/') && r.status() >= 400) {
      apiErrors.push(`${r.status()} ${r.request().method()} ${u}`)
    }
  })

  try {
    log('baseURL =', BASE_URL)
    const versionResp = await page.request.get(`${BASE_URL}/version.json`).catch(() => null)
    if (versionResp && versionResp.ok()) {
      const v = await versionResp.json()
      log('站点版本 =', JSON.stringify(v))
    }

    // 1) 登录
    log('使用账号登录：', getLoginUsername(), 'type=', getLoginType())
    await loginWithRealAccount(page, {
      loginType: getLoginType(),
      username: getLoginUsername(),
      password: getLoginPassword()
    })
    log('登录后 URL =', page.url())
    await page.screenshot({ path: path.join(OUT_DIR, '01-after-login.png') })

    // 2) 打开价格备案申请列表
    log('打开列表：', LIST_PATH)
    await page.goto(`${BASE_URL}${LIST_PATH}`, { waitUntil: 'domcontentloaded' })
    await page.waitForLoadState('networkidle').catch(() => {})
    await page.locator('.el-loading-mask:visible').first().waitFor({ state: 'hidden', timeout: 30000 }).catch(() => {})
    await page.screenshot({ path: path.join(OUT_DIR, '02-list.png'), fullPage: true })

    // 3) 进入新增页（价格备案申请）
    const addBtn = page.locator('.list-card button, .list-card .el-button').filter({ hasText: /新增|申请/ }).first()
    let entered = false
    if (await addBtn.count()) {
      log('点击新增按钮')
      await addBtn.click()
      await page.waitForTimeout(1500)
      entered = true
    } else {
      log('未找到新增按钮，尝试直接访问 detail')
      await page.goto(`${BASE_URL}/#/commercialHousingSales/priceFiling/recordPriceMngSuzhou/detail?formMode=add`, { waitUntil: 'domcontentloaded' })
      await page.waitForTimeout(2000)
      entered = true
    }
    await page.screenshot({ path: path.join(OUT_DIR, '03-detail.png'), fullPage: true })
    log('详情页 URL =', page.url())

    // 4) 点击「项目名称」选择框，打开弹窗
    const projInput = page.locator('input[placeholder="请选择项目名称"]').first()
    await projInput.waitFor({ state: 'visible', timeout: 20000 })
    log('点击项目名称选择框')
    await projInput.click()

    // 5) 等弹窗表格出现
    const dialog = page.locator('.el-dialog:visible, .zs-dialog:visible').filter({ hasText: '项目名称' }).first()
    await dialog.waitFor({ state: 'visible', timeout: 20000 })
    await page.locator('.el-loading-mask:visible').first().waitFor({ state: 'hidden', timeout: 30000 }).catch(() => {})
    await page.waitForTimeout(1200)
    await page.screenshot({ path: path.join(OUT_DIR, '04-project-dialog.png') })

    // 6) 定位表头索引，读取该列每个单元格文本
    const headers = await dialog.locator('thead th').allInnerTexts().catch(() => [])
    log('表头 =', JSON.stringify(headers.map((h) => h.trim())))
    const colIdx = headers.findIndex((h) => h.includes('项目所在地'))
    log('项目所在地列索引 =', colIdx)

    const rows = dialog.locator('tbody tr')
    const rowCount = await rows.count()
    log('数据行数 =', rowCount)

    const cells = []
    for (let i = 0; i < rowCount; i++) {
      const tds = rows.nth(i).locator('td')
      const tdCount = await tds.count()
      if (colIdx >= 0 && colIdx < tdCount) {
        const text = (await tds.nth(colIdx).innerText()).trim()
        const firstCell = (await tds.first().innerText()).trim()
        cells.push({ row: i + 1, firstCell, region: text })
      }
    }
    log('「项目所在地」取值 =', JSON.stringify(cells, null, 2))

    const nonEmpty = cells.filter((c) => c.region)
    const result = {
      baseUrl: BASE_URL,
      columnIndex: colIdx,
      rowCount,
      nonEmptyCount: nonEmpty.length,
      sample: cells.slice(0, 5),
      pass: colIdx >= 0 && rowCount > 0 && nonEmpty.length > 0
    }
    fs.writeFileSync(path.join(OUT_DIR, 'result.json'), JSON.stringify(result, null, 2))
    log('=== 结论 ===', result.pass ? 'PASS：项目所在地有值' : 'FAIL：项目所在地仍为空')

    // 7) 高亮截图：把「项目所在地」列圈出来
    if (colIdx >= 0) {
      await page.evaluate((idx) => {
        const dlg = [...document.querySelectorAll('.el-dialog, .zs-dialog')].find((d) => d.innerText.includes('项目名称'))
        if (!dlg) return
        dlg.querySelectorAll('tbody tr').forEach((tr) => {
          const td = tr.children[idx]
          if (td) {
            td.style.background = '#fff3cd'
            td.style.outline = '2px solid #ff9800'
            td.style.fontWeight = '700'
          }
        })
        const th = dlg.querySelectorAll('thead th')[idx]
        if (th) { th.style.background = '#ffecb3' }
      }, colIdx)
      await page.waitForTimeout(400)
      await page.screenshot({ path: path.join(OUT_DIR, '05-project-dialog-highlight.png') })
      const clip = await dialog.boundingBox()
      if (clip) {
        await page.screenshot({ path: path.join(OUT_DIR, '06-dialog-crop.png'), clip })
      }
    }

    if (apiErrors.length) log('接口异常（>=400）：', JSON.stringify(apiErrors.slice(0, 10), null, 2))
    else log('接口异常：无')

    await browser.close()
    process.exitCode = result.pass ? 0 : 2
  } catch (err) {
    log('执行失败：', err && err.stack ? err.stack : String(err))
    await page.screenshot({ path: path.join(OUT_DIR, '99-failure.png'), fullPage: true }).catch(() => {})
    await browser.close()
    process.exitCode = 1
  }
}

main()

